#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_logo.py  ·  встраивает логотип «стручок» в STRUCHORD.html
================================================================
Что делает (всё в одном файле, ничего доустанавливать не нужно):

  1. вставляет в HTML определения знаков (стручок и перец, один раз);
  2. ставит знак в шапку главного экрана вместо медиатора;
  3. ставит знак в шапку редактора вместо медиатора;
  4. заменяет иконку вкладки браузера (favicon 32 px);
  5. заменяет иконку «на экран Домой» (apple-touch-icon 180 px);
  6. на телефоне БОЛЬШЕ НЕ ПРЯЧЕТ знак — показывает уменьшенным;
  7. в схемах «Перец», «Слива» и «Малина» показывает их собственные знаки
     (векторы с картинок владельца), в остальных — стручок;
  8. рядом с HTML кладёт три PNG для Android (192, 512, maskable 512);
  8. если найдёт manifest.json — прописывает в него эти иконки (с бэкапом).

Запуск:
    python3 patch_logo.py                       # применит к ./STRUCHORD.html
    python3 patch_logo.py --dry-run             # только проверить, ничего не писать
    python3 patch_logo.py --input путь/STRUCHORD.html
    python3 patch_logo.py --strategy mono       # цвет знака: color | mono | two-tone

Каждая замена ищется по ТОЧНОМУ тексту и должна встретиться РОВНО ОДИН раз.
Если хоть одна не нашлась — скрипт ничего не пишет и печатает, что именно не так.
"""

import argparse
import json
import os
import re
import shutil
import sys

VERSION = "1.5"

