def _ind(svg):
    return "\n".join("      " + ln for ln in svg.splitlines())


#    Цвета знаков схем. У перца цвета сняты с картинки и фиксированы,
#    у сливы и малины берутся из самой схемы: контур — цвет текста
#    (он всегда противоположен фону), тело — brand, тень и блик считаются
#    от brand, поэтому знак остаётся в палитре схемы при любой правке темы.
FRUIT_VARS = {
    "pepper": {
        "light": ("--sm-line: var(--color-text-primary); --sm-bean: var(--color-brand); "
                  "--sm-bean2: #b7080f; --sm-stem: #617644; --sm-shine: #f9afa9;"),
        "dark":  ("--sm-line: var(--color-text-primary); --sm-bean: var(--color-brand); "
                  "--sm-bean2: #b7080f; --sm-stem: #8fa267; --sm-shine: #f9afa9;"),
    },
}
#    Лист у сливы и малины — зелёный, как на картинке: это единственная деталь,
#    которую нельзя выводить из бренда (иначе лист становится коричневым).
#    Лист у сливы и малины: на светлой теме зелёный (как на картинке), на тёмной —
#    прозрачный, как у стручка. Цвет нельзя выводить из схемы — иначе лист коричневый.
def _recipe(leaf):
    return ("--sm-line: var(--color-text-primary); --sm-bean: var(--color-brand); "
            "--sm-bean2: color-mix(in srgb, var(--color-brand) 55%, #000); "
            "--sm-shine: color-mix(in srgb, var(--color-brand) 28%, #fff); "
            "--sm-leaf: " + leaf + ";")


# Лист: на светлой теме зелёный, как на картинке; на тёмной — не закрашен,
# как у стручка (виден фон, остаются контур и прожилки).
FRUIT_VARS["plum"] = {"light": _recipe("#5d7a3e"), "dark": _recipe("transparent")}
FRUIT_VARS["raspberry"] = {"light": _recipe("#5d7a3e"), "dark": _recipe("transparent")}

FRUITS = [("pepper", "Перец", "PEPPER"),
          ("plum", "Слива", "PLUM"),
          ("raspberry", "Малина", "RASPBERRY")]

# ══════════════════════════════════════════════════════════════════════
#  ЦВЕТ ЗНАКА. Меняется одна строка — больше ничего трогать не нужно.
#    "line"     — только контур, цветом акцента темы. Самый чёткий на мелком
#                 размере: взят из svg_line/line-icon-currentColor.svg
#    "line-brand" — то же, но цветом brand (тем же, что у надписи STRUCHORD)
#    "color"    — как в исходнике: контур + олива + терракота
#    "mono"     — все четыре слоя одним цветом акцента (бобы становятся пятном)
#    "two-tone" — контур цветом текста, бобы цветом brand темы
# ══════════════════════════════════════════════════════════════════════
