#    Контур = цвет основного текста (он всегда противоположен фону),
#    тело = brand схемы (#f50029), кайма сегментов — тёмно-красная,
#    блик — розовый из присланной картинки, стебель — зелёный.
PEPPER_LIGHT = ("--sm-line: var(--color-text-primary); --sm-bean: var(--color-brand); "
                "--sm-bean2: #b7080f; --sm-stem: #617644; --sm-shine: #f9afa9;")
