# ══════════════════════════════════════════════════════════════════════
#  ВСПОМОГАТЕЛЬНОЕ
# ══════════════════════════════════════════════════════════════════════
class Fail(Exception):
    pass


def read(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return f.read()


def write(path, text):
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(text)


def one(text, anchor, name):
    """Возвращает позицию якоря, если он встречается ровно один раз."""
    n = text.count(anchor)
    if n != 1:
        raise Fail("%s — найдено %d вхождений вместо 1.\n"
                   "   Якорь: %r" % (name, n, anchor[:160]))
    return text.index(anchor)


def swap(text, old, new, name, done_marker=None):
    """Заменяет old на new. Если old нет, но new уже есть — считает, что применено."""
    n = text.count(old)
    if n == 0:
        if done_marker and text.count(done_marker) > 0:
            return text, "уже было"
        raise Fail("%s — текст для замены не найден.\n"
                   "   Искали: %r" % (name, old[:200]))
    if n != 1:
        raise Fail("%s — найдено %d вхождений вместо 1.\n"
                   "   Искали: %r" % (name, n, old[:200]))
    return text.replace(old, new, 1), "заменено"


def bump_version(text):
    """Поднимает номер версии приложения ровно на один шаг: 0.682 → 0.683, 0.699 → 0.700."""
    hits = VER_ANY.findall(text)
    if not hits:
        raise Fail("8. номер версии — в файле нет строки вида «· ver 0.682».\n"
                   "   Номер версии стоит в <span id=\"devPanelTrigger\">.")
    if len(hits) != 1:
        raise Fail("8. номер версии — найдено %d вхождений вместо 1." % len(hits))
    old = "%s.%s" % (hits[0][1], hits[0][2])
    new = "%s.%d" % (hits[0][1], int(hits[0][2]) + 1)
    text = VER_ANY.sub(lambda m: m.group(1) + new, text, count=1)
    return text, "обновлено: %s → %s" % (old, new)


def upgrade(text, defs, css, report):
    """Доводит до текущей версии файл, где знак уже стоит.

    Нужна тем, кто применял прошлую версию патча: обычные шаги видят свои
    маркеры и пишут «уже было», а новые знаки при этом не появились бы.
    Меняются три вещи: блок определения знаков, блок стилей и ссылки <use>.
    Каждая правка делается, только если содержимое реально отличается,
    поэтому повторный запуск ничего не трогает.
    """
    if 'id="struchord-logo-defs"' not in text:
        return text, ""          # чистый файл — всё вставят шаги 1 и 2

    done = []
    # сравниваем и подставляем только сам блок <svg …> — комментарий перед ним
    # содержит номер версии и к блоку не относится
    new_defs = defs[defs.index('<svg id="struchord-logo-defs"'):].strip()

    m = re.search(r'<svg id="struchord-logo-defs".*?</svg>', text, re.S)
    if not m:
        raise Fail("блок определения знака есть, но не разбирается — "
                   "возьмите чистую копию 0.682")
    if m.group(0).strip() != new_defs:
        missing = [sid for sid in ("struchord-pod", "struchord-pepper",
                                   "struchord-plum", "struchord-raspberry")
                   if 'id="%s"' % sid not in m.group(0)]
        text = text[:m.start()] + new_defs + text[m.end():]
        done.append("определение знака" + (" (не было: %s)" % ", ".join(missing) if missing else ""))

    old_css = None
    cm = re.search(r'<style id="struchord-logo-css">.*?</style>', text, re.S)
    if not cm:
        raise Fail("блок стилей знака есть, но не разбирается — "
                   "возьмите чистую копию 0.682")
    old_css = cm.group(0).strip()
    new_css = css[css.index('<style id="struchord-logo-css">'):].strip()
    if old_css != new_css:
        text = text[:cm.start()] + new_css + text[cm.end():]
        done.append("стили знака")

    # ссылки <use>: три возможных состояния — без класса, с перцем, с тремя знаками
    if 'class="mark-raspberry"' not in text:
        plain = '<use href="#struchord-pod"/>'
        pair = ('<use class="mark-pod" href="#struchord-pod"/>'
                '<use class="mark-pepper" href="#struchord-pepper"/>')
        if text.count(plain) == 2:
            text = text.replace(plain, _MARKS)
            done.append("ссылки на знак")
        elif text.count(pair) == 2:
            text = text.replace(pair, _MARKS)
            done.append("ссылки на знак")
        else:
            raise Fail('ссылок на знак не 2, а %d (без класса) и %d (с перцем) — '
                       'возьмите чистую копию 0.682' % (text.count(plain), text.count(pair)))

    # номер версии в двух комментариях рядом с блоками тоже освежаем
    text2 = re.sub(r'(патч_logo\.py|patch_logo\.py) v\d+(\.\d+)*', 'patch_logo.py v%s' % VERSION, text)
    if text2 != text:
        text = text2
        if not done:
            done.append("номер версии в комментариях")

    return text, ("обновлено: " + ", ".join(done)) if done else "уже было"


def insert_once(text, anchor, payload, name, marker):
    """Вставка блока. Если маркер уже есть ровно один раз — считает, что сделано.

    Нужна для шагов, у которых якорь (<body>, </head>) остаётся в файле и после
    патча: без этой проверки повторный запуск вставил бы блок второй раз.
    """
    n = text.count(marker)
    if n == 1:
        return text, "уже было"
    if n > 1:
        raise Fail("%s — маркер %r встречается %d раза. Файл уже испорчен "
                   "повторным применением патча; возьмите копию из .bak."
                   % (name, marker, n))
    return swap(text, anchor, payload, name)


