def css_block(strategy):
    if strategy == "table":
        return CSS % dict(ver=VERSION, color_css=table_css())

    if strategy == "color":
        light = ("--sm-line: #2B2A25; --sm-bean: #6E7A45; "
                 "--sm-bean2: #A75A38; --sm-shine: #FBF8F0;")
        dark = ("html[data-theme='dark'] .struchord-mark { --sm-line: #F4F0E4; "
                "--sm-bean: #8A9161; --sm-bean2: #BC7350; --sm-shine: #FBF8F0; }")
    elif strategy == "mono":
        light = C_SET + " color: var(--color-accent);"
        dark = ""
    elif strategy == "line":
        light = "--sm-line: currentColor; color: var(--color-accent);"
        dark = ""
    elif strategy == "line-brand":
        light = "--sm-line: currentColor; color: var(--color-brand);"
        dark = ""
    elif strategy == "two-tone":
        light = D_SET
        dark = ""
    else:
        raise Fail("неизвестная стратегия: %r" % strategy)

    css = CSS % dict(ver=VERSION, color_css=fruit_css())
    css = css.replace("      .struchord-mark {\n", "      .struchord-mark { " + light + "\n", 1)
    if dark:
        css = css.replace("      /* Шапка главного экрана", "      " + dark + "\n      /* Шапка главного экрана", 1)
    return css


