# Номер версии приложения не задан жёстко: патч берёт его из файла и делает
# следующий шаг. Поэтому он одинаково годится и для 0.682, и для 0.699 —
# подгонять константы под файл не нужно.
VER_ANY = re.compile(r'(·\s*ver\s+)(\d+)\.(\d+)')

OLD_HOME_HTML = ('<span class="home-brand-mark" aria-hidden="true">'
                 '<i class="ti ti-guitar-pick"></i></span>')

OLD_EDITOR_HTML = ('<i class="ti ti-guitar-pick" '
                   'style="font-size: 1.375rem; color: var(--color-accent)"></i>')


# ══════════════════════════════════════════════════════════════════════
#  ШАГИ
# ══════════════════════════════════════════════════════════════════════
BODY_COLOR = (
    '          <path d="%(terra)s" fill="var(--sm-bean2, #A75A38)" fill-rule="evenodd"/>\n'
    '          <path d="%(olive)s" fill="var(--sm-bean, #6E7A45)" fill-rule="evenodd"/>\n'
    '          <path d="%(line)s"  fill="var(--sm-line, #2B2A25)" fill-rule="evenodd"/>\n'
    '          <path d="%(shine)s" fill="var(--sm-shine, #FBF8F0)" fill-rule="evenodd"/>')
BODY_LINE = ('          <path d="%(line)s" fill="var(--sm-line, currentColor)" fill-rule="evenodd"/>')


def patch_html(text, strategy, report):
    # каким файл был до правок — нужно, чтобы шаг с номером версии не срабатывал дважды
    text_before = text
    # 1. определение знака + стили (одним куском, чтобы не искать <body> дважды)
    body = BODY_LINE if strategy in ("line", "line-brand") else BODY_COLOR
    defs = DEFS % dict(ver=VERSION, pepper=_ind(PEPPER), plum=_ind(PLUM),
                       raspberry=_ind(RASPBERRY), body=body % dict(
                           terra=D_TERRA, olive=D_OLIVE, line=D_LINE, shine=D_SHINE))
    # 0. файл, где знак уже стоит без перца, доводим до текущей версии
    css = css_block(strategy)
    text, st = upgrade(text, defs, css, report)
    if st:
        report.append(("0. обновление до текущей версии знака", st))

    text, st = insert_once(text, A_BODY, defs + "\n", "1. определение знака",
                           'id="struchord-pod"')
    report.append(("1. определение знака в HTML", st))

    # 2. стили — вставляем перед </head>
    text, st = insert_once(text, A_HEAD, css + "  </head>\n", "2. стили логотипа",
                           'id="struchord-logo-css"')
    report.append(("2. стили логотипа (цвет: %s)" % strategy, st))


    # 3. шапка главного экрана
    text, st = swap(text, OLD_HOME_HTML, USE_HOME, "3. знак в шапке главного экрана",
                    'class="mark-raspberry"')
    report.append(("3. шапка главного экрана: медиатор → стручок", st))

    # 4. шапка редактора
    text, st = swap(text, OLD_EDITOR_HTML, USE_EDITOR, "4. знак в шапке редактора",
                    'class="mark-raspberry"')
    report.append(("4. шапка редактора: медиатор → стручок", st))

    # 5. контейнер знака на главном экране
    text, st = swap(text, OLD_HOME_MARK_CSS, NEW_HOME_MARK_CSS, "5. размер контейнера знака",
                    "контейнер знака подогнан")
    report.append(("5. контейнер знака: 22×22 → 28 px по высоте", st))

    # 6. на телефоне знак показываем, а не прячем
    text, st = swap(text, OLD_MOBILE_HIDE, NEW_MOBILE_HIDE, "6. знак на телефоне",
                    NEW_MOBILE_HIDE)
    report.append(("6. телефон: знак больше не скрыт (20 px)", st))

    # 7. шапка редактора на телефоне
    text, st = swap(text, OLD_EDITOR_HIDE, NEW_EDITOR_HIDE, "7. шапка редактора на телефоне",
                    "в шапке редактора знак остаётся скрыт")
    report.append(("7. телефон: в шапке редактора знак скрыт (как и было)", st))

    # 8. номер версии
    if ("patch_logo.py v%s" % VERSION) in text_before:
        st = "уже этой версии патча — номер не двигаю"
    else:
        text, st = bump_version(text)
    report.append(("8. номер версии приложения", st))

    # 9. favicon
    new_fav = ('<link rel="icon" type="image/png" sizes="32x32" '
               'href="data:image/png;base64,%s" />' % PNG_FAVICON_32)
    text, st = swap(text, OLD_FAVICON, new_fav, "9. иконка вкладки", PNG_FAVICON_32[:40])
    report.append(("9. иконка вкладки браузера (favicon 32 px)", st))

    # 10. apple-touch-icon
    new_apple = ('<link rel="apple-touch-icon" sizes="180x180" '
                 'href="data:image/png;base64,%s" />' % PNG_APPLE_180)
    text, st = swap(text, OLD_APPLE, new_apple, "10. иконка «на экран Домой»", PNG_APPLE_180[:40])
    report.append(("10. иконка «на экран Домой» (180 px)", st))

    return text


def check(text):
    """Проверки после правки. Возвращает список строк-замечаний."""
    problems = []
    if text.count('id="struchord-pod"') != 1:
        problems.append("определение знака #struchord-pod должно быть ровно одно")
    marks = [("pod", "стручок"), ("pepper", "перец"), ("plum", "слива"),
             ("raspberry", "малина")]
    for mid, name in marks:
        if text.count('id="struchord-%s"' % mid) != 1:
            problems.append("определение знака #struchord-%s должно быть ровно одно" % mid)
        n = text.count('<use class="mark-%s" href="#struchord-%s"' % (mid, mid))
        if n != 2:
            problems.append("%s должен использоваться ровно 2 раза (главный экран + редактор), "
                            "а используется %d" % (name, n))
    for piece in ("mark-pepper, .struchord-mark .mark-plum", "mark-pod { display: none",
                  "mark-plum { display: inline", "mark-raspberry { display: inline",
                  "--sm-leaf: #5d7a3e", "--sm-leaf: transparent"):
        if piece not in text:
            problems.append("в стилях нет правила %r" % piece)
    if "ti-guitar-pick\"></i>" in text or "ti ti-guitar-pick\" style" in text:
        problems.append("остался старый медиатор в разметке")
    if text.count("<body>") < 1:
        problems.append("пропал <body>")
    if text.count("</html>") != 1:
        problems.append("нарушена структура документа (</html> не один)")
    if ".struchord-mark" not in text:
        problems.append("нет стилей знака")
    return problems


def write_icons(folder, report):
    made = []
    for name, data in (("icon-192.png", PNG_192),
                       ("icon-512.png", PNG_512),
                       ("icon-512-maskable.png", PNG_MASKABLE_512)):
        path = os.path.join(folder, name)
        with open(path, "wb") as f:
            f.write(__import__("base64").b64decode(data))
        made.append((name, os.path.getsize(path)))
    report.append(("11. PNG для Android записаны рядом с HTML",
                   ", ".join("%s (%d Б)" % m for m in made)))
    return made


def patch_manifest(path, report):
    icons = [
        {"src": "icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
        {"src": "icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
        {"src": "icon-512-maskable.png", "sizes": "512x512", "type": "image/png",
         "purpose": "maskable"},
    ]
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    shutil.copy2(path, path + ".bak")
    data["icons"] = icons
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    report.append(("12. manifest.json: прописаны 3 иконки", "бэкап рядом: manifest.json.bak"))


# ══════════════════════════════════════════════════════════════════════
#  ГЛАВНОЕ
# ══════════════════════════════════════════════════════════════════════
def main():
    ap = argparse.ArgumentParser(description="Встраивает логотип в STRUCHORD.html")
    ap.add_argument("--input", default="STRUCHORD.html")
    ap.add_argument("--strategy", default=DEFAULT_STRATEGY,
                    choices=["table", "line", "line-brand", "color", "mono", "two-tone"])
    ap.add_argument("--manifest", default=None,
                    help="путь к manifest.json (по умолчанию — рядом с HTML, если есть)")
    ap.add_argument("--no-icons", action="store_true", help="не писать PNG и не трогать manifest")
    ap.add_argument("--dry-run", action="store_true", help="проверить и ничего не писать")
    args = ap.parse_args()

    src = args.input
    if not os.path.isfile(src):
        print("НЕ НАЙДЕН ФАЙЛ: %s" % src)
        print("Положите patch_logo.py рядом со STRUCHORD.html или укажите --input")
        return 2

    text = read(src)
    size_before = os.path.getsize(src)
    report = []

    try:
        new_text = patch_html(text, args.strategy, report)
    except Fail as e:
        print("\nПАТЧ НЕ ПРИМЕНЁН — версия файла не та, которую ждёт патч.\n")
        print(str(e))
        print("\nНичего не изменено.")
        return 1

    problems = check(new_text)
    if problems:
        print("\nПАТЧ НЕ ПРИМЕНЁН — после правки не сходится:\n")
        for p in problems:
            print("  · " + p)
        print("\nНичего не изменено.")
        return 1

    if args.dry_run:
        print("\nDRY-RUN. Всё сходится, можно применять. Ничего не записано.\n")
        for name, st in report:
            print("  ✓ %-52s %s" % (name, st))
        return 0

    # бэкап
    backup = src + ".bak"
    if not os.path.exists(backup):
        shutil.copy2(src, backup)
        bak_note = "создан %s" % os.path.basename(backup)
    else:
        bak_note = "%s уже был — не перезаписан" % os.path.basename(backup)

    write(src, new_text)

    if not args.no_icons:
        folder = os.path.dirname(os.path.abspath(src))
        write_icons(folder, report)
        man = args.manifest or os.path.join(folder, "manifest.json")
        if os.path.isfile(man):
            try:
                patch_manifest(man, report)
            except Exception as e:
                report.append(("12. manifest.json — НЕ обновлён", str(e)))
        else:
            report.append(("12. manifest.json", "файла рядом нет — пропущено"))

    size_after = os.path.getsize(src)

    print("\n" + "═" * 68)
    print(" ПАТЧ ПРИМЕНЁН")
    print("═" * 68)
    print(" Файл:      %s" % src)
    print(" Бэкап:     %s" % bak_note)
    print(" Размер:    {:,} → {:,} байт ({:+,})".format(size_before, size_after,
                                                        size_after - size_before).replace(",", " "))
    if args.strategy == "table":
        print(" Цвет знака: по таблице — у каждой схемы свой вариант")
        print("─" * 68)
        print("  %-10s %-9s %-9s" % ("схема", "светлая", "тёмная"))
        for sid, name, lv, dv in SCHEME_TABLE:
            print("  %-10s %-9s %-9s" % (name, lv.upper(), dv.upper()))
    else:
        print(" Цвет знака: %s (одна настройка для всех схем)" % args.strategy)
    print("─" * 68)
    for name, st in report:
        print("  ✓ %-52s %s" % (name, st))
    print("─" * 68)
    print(" Проверки после правки: пройдено %d, замечаний 0" % len(report))
    print("═" * 68)
    print("""
 ЧТО ДЕЛАТЬ ДАЛЬШЕ
 1. Откройте STRUCHORD.html в браузере.
 2. Если приложение установлено как PWA (иконка на «Домой»):
    обновите страницу два раза подряд — старый кэш заменится новым.
 3. Проверьте:
    · на главном экране слева от STRUCHORD стоит стручок;
    · в редакторе — тоже, вместо медиатора;
    · переключите тему (☾) — знак меняет цвета вместе с темой;
    · выберите схемы «Перец», «Слива», «Малина» — вместо стручка появятся
      перец, слива и малина;
    · переключите цветовую схему — знак остаётся читаемым;
    · сузьте окно до телефона — на главном экране знак уменьшается,
      но не исчезает (в шапке редактора на телефоне его нет: не хватает места).

 ЕСЛИ НУЖЕН ДРУГОЙ ЦВЕТ ЗНАКА
 Сейчас цвет задан таблицей: в самом patch_logo.py есть список SCHEME_TABLE.
 Поставьте нужную букву у нужной схемы и запустите на бэкапе:
    cp STRUCHORD.html.bak STRUCHORD.html
    python3 patch_logo.py
 Либо одной настройкой на все схемы сразу:
    python3 patch_logo.py --strategy line    (контуром — рекомендуется)
""")
    return 0


if __name__ == "__main__":
    sys.exit(main())
